        return String.format("%s.%s.%s-%s",
                cpf.substring(0, 3),
                cpf.substring(3, 6),
                cpf.substring(6, 9),
                cpf.substring(9, 11));
    }

    private static String getRoomTypeByNumber(int roomNumber) {
        if (roomNumber < 200) {
            return "STANDARD";
        } else if (roomNumber < 300) {
            return "DELUXE";
        } else {
            return "SUITE";
        }
    }
